 function revisionFlashcards(){
 const cards=[
 ["A&P — Heart","Which chamber pumps oxygenated blood to the body?","Left ventricle.","मुटुको left ventricle ले oxygenated blood शरीरमा पठाउँछ।"],
 ["A&P — Kidney","What is the functional unit of the kidney?","Nephron.","मिर्गौलाको functional unit nephron हो।"],
 ["A&P — Respiration","Where does gas exchange mainly occur?","Alveoli.","फोक्सोको alveoli मा मुख्य gas exchange हुन्छ।"],
 ["Community — Epidemiology","Incidence measures what?","New cases occurring in a population during a specified period.","Incidence ले निश्चित अवधिमा देखिएका नयाँ केस जनाउँछ।"],
 ["Community — Epidemiology","Prevalence measures what?","All existing cases in a population at a given time or period.","Prevalence ले निश्चित समय/अवधिमा रहेका सबै केस जनाउँछ।"],
 ["Community — MCH","How long is exclusive breastfeeding recommended?","The first 6 months of life.","सामान्यतया जन्मेको पहिलो ६ महिना exclusive breastfeeding सिफारिस हुन्छ।"],
 ["Medicine — Diabetes","Which pancreatic cells produce insulin?","Beta cells of the islets of Langerhans.","Pancreas का islets का beta cells ले insulin बनाउँछन्।"],
 ["Medicine — Stroke","What does FAST stand for?","Face, Arm, Speech, Time.","अनुहार, हात, बोली र तुरुन्त सहायता गर्ने समय।"],
 ["Medicine — Asthma","Name two common features of asthma exacerbation.","Wheezing and breathlessness/chest tightness.","दम बढ्दा wheezing र सास फेर्न गाह्रो/छाती कसिने हुन सक्छ।"],
 ["Surgery — First Aid","What is the first aid for a thermal burn?","Cool under cool running water; do not use ice or toothpaste.","पोलाइमा चिसो बग्ने पानी प्रयोग; बरफ वा टुथपेस्ट नलगाउने।"],
 ["Surgery — Trauma","What should you do with an exposed bone in an open fracture?","Cover/protect it; never push it back into the wound.","खुला fracture को हड्डी नधकेल्ने; सफा dressing ले छोपेर urgent care।"],
 ["Surgery — Emergency","What is the priority for severe external bleeding?","Firm direct pressure and urgent emergency assistance.","धेरै बाहिरी रक्तस्रावमा direct pressure र तुरुन्त emergency सहायता।"],
 ["Pharmacy — Units","Convert 1 gram to milligrams.","1 g = 1,000 mg.","१ ग्राम = १,००० मिलिग्राम।"],
 ["Pharmacy — Calculation","What is the basic formula for volume to administer?","Prescribed dose ÷ available dose × available volume; check units and concentration.","दिनुपर्ने volume = चाहिएको dose ÷ उपलब्ध dose × उपलब्ध volume; unit जाँच्नुहोस्।"],
 ["Pharmacy — Safe use","Do antibiotics treat viral common colds?","No. Antibiotics are not effective against viruses; use only when clinically indicated.","Antibiotic ले virus मार्दैन; आवश्यक हुँदा मात्र चिकित्सकीय सल्लाहअनुसार प्रयोग हुन्छ।"],
 ["Pathology — Specimen","What is important when collecting a urine culture specimen?","Clean-catch midstream urine in a sterile container, promptly transported.","सफा midstream urine sterile container मा सङ्कलन गरी छिटो पठाउनुहोस्।"],
 ["Pathology — Malaria","Which blood film methods are used for malaria microscopy?","Thick and thin peripheral blood films.","मलेरिया जाँचमा thick र thin peripheral blood film प्रयोग हुन्छ।"],
 ["Pathology — Quality","Name two ways to reduce specimen errors.","Correct patient identification and correct labelling/container/transport.","सही बिरामी पहिचान र सही label/container/transport ले त्रुटि घटाउँछ।"]
 ];
 shell("HA Revision Flashcards",'<p class="np">पहिले प्रश्न सम्झनुहोस्, त्यसपछि Reveal Answer थिचेर उत्तर हेर्नुहोस्। English + नेपाली।</p>'+cards.map((c,i)=>'<article class="ha-note"><small>'+esc(c[0])+'</small><p><b>'+esc(c[1])+'</b></p><button type="button" data-ha2-reveal="'+i+'">Reveal Answer / उत्तर हेर्नुहोस्</button><div id="ha2card'+i+'" hidden><p><b>'+esc(c[2])+'</b></p><p class="np">'+esc(c[3])+'</p></div></article>').join(''));
 }
 function confusedConcepts(){
 const pairs=[
 ["Incidence vs Prevalence","Incidence = new cases over a period. Prevalence = all existing cases at a point/period.","Incidence = निश्चित अवधिका नयाँ केस। Prevalence = त्यस समयका सबै विद्यमान केस।"],
 ["Screening vs Diagnosis","Screening identifies people who may need further testing; diagnosis establishes disease using clinical assessment and appropriate tests.","Screening ले थप जाँच चाहिने व्यक्ति छान्छ; diagnosis ले clinical assessment र उपयुक्त जाँचबाट रोग निर्धारण गर्छ।"],
 ["Sensitivity vs Specificity","Sensitivity: correctly positive among people with disease. Specificity: correctly negative among people without disease.","Sensitivity = रोग भएकामा सही positive; Specificity = रोग नभएकामा सही negative।"],
 ["Sterilisation vs Disinfection","Sterilisation destroys all forms of microbial life, including spores. Disinfection reduces/destroys many pathogens but may not kill spores.","Sterilisation ले spores सहित सबै microbial life नष्ट गर्छ; disinfection ले धेरै रोगाणु घटाउँछ/नष्ट गर्छ तर spores नष्ट नहुन सक्छ।"],
 ["Antiseptic vs Disinfectant","Antiseptics are used on living tissue; disinfectants are used on inanimate objects/surfaces according to product instructions.","Antiseptic जीवित tissue मा; disinfectant निर्जीव सतह/वस्तुमा प्रयोग हुन्छ।"],
 ["Hypoglycaemia vs Hyperglycaemia","Hypoglycaemia = low blood glucose; hyperglycaemia = high blood glucose. Symptoms and management differ.","Hypoglycaemia = रगतमा glucose कम; Hyperglycaemia = glucose बढी।"],
 ["Artery vs Vein","Arteries carry blood away from the heart; veins carry blood toward the heart. Oxygen content has exceptions, such as pulmonary vessels.","Artery ले मुटुबाट टाढा र vein ले मुटुतर्फ रगत लैजान्छ। Oxygen मात्रा pulmonary vessels मा अपवाद हुन्छ।"],
 ["Sign vs Symptom","A sign is objectively observed/measured; a symptom is experienced and reported by the patient.","Sign वस्तुगत रूपमा देखिने/मापन हुने; symptom बिरामीले महसुस गरी बताउने कुरा हो।"],
 ["Contamination vs Infection","Contamination is unwanted presence of microbes/material; infection is invasion and multiplication of pathogens in the body.","Contamination = अनावश्यक जीवाणु/पदार्थको उपस्थिति; infection = शरीरमा रोगाणुको प्रवेश र वृद्धि।"],
 ["Efficacy vs Effectiveness","Efficacy is benefit under controlled/ideal conditions; effectiveness is benefit in routine real-world practice.","Efficacy = नियन्त्रित/आदर्श अवस्थामा प्रभाव; effectiveness = वास्तविक सेवामा देखिने प्रभाव।"],
 ["Adverse effect vs Allergy","An adverse effect is an unwanted response to a medicine; an allergy is an immune-mediated hypersensitivity reaction.","Adverse effect औषधिको अनिच्छित असर हो; allergy प्रतिरक्षा प्रणालीको hypersensitivity प्रतिक्रिया हो।"],
 ["Incidence vs Attack rate","Attack rate is a proportion of at-risk people who become ill during an outbreak; it is a type of cumulative incidence.","Attack rate प्रकोपमा जोखिममा रहेका मध्ये बिरामी हुने अनुपात हो; यो cumulative incidence को एक प्रकार हो।"]
 ];
 shell("Frequently Confused Concepts",'<p class="np">NHPC तयारीमा मिल्दोजुल्दो शब्दको फरक छुट्याउनुहोस्।</p>'+pairs.map((p,i)=>'<article class="ha-note"><b>'+(i+1)+'. '+esc(p[0])+'</b><p>'+esc(p[1])+'</p><p class="np">'+esc(p[2])+'</p></article>').join(''));
 }
